}

@code {
    private AppointmentModel Model { get; set; } = new();
    private bool _showStep2;
    private bool _submitted;
    private List<string> _doctors = new();
    private List<string> _timeSlots = new();
    private Dictionary<string, string> _fieldErrors = new();

    private EditContext? _editContext;

    protected override async Task OnInitializedAsync()
    {
        _doctors = await AppointmentService.GetDoctorsAsync();
    }

    private async Task CheckAvailability()
    {
        _fieldErrors.Clear();

        // Validate step 1 fields manually
        var isValid = true;
        if (string.IsNullOrWhiteSpace(Model.PatientName))
            isValid = false;
        if (string.IsNullOrWhiteSpace(Model.Email) || !IsValidEmail(Model.Email))
            isValid = false;
        if (string.IsNullOrWhiteSpace(Model.Phone))
            isValid = false;
        if (string.IsNullOrWhiteSpace(Model.InsuranceProvider))
            isValid = false;

        if (!isValid)
        {
            // Trigger validation display by creating and validating an EditContext
            var ctx = new EditContext(Model);
            ctx.Validate();
            return;
        }

        // Call server-side validation
        var errors = await AppointmentService.ValidatePatientAsync(
            Model.Email, Model.InsuranceProvider, "", null);

        if (errors.Count > 0)
        {
            _fieldErrors = errors;
            return;
        }

        _showStep2 = true;
    }

    private async Task OnDoctorChanged()
    {
        _timeSlots.Clear();
        Model.TimeSlot = string.Empty;
        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            _timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
                Model.Doctor, Model.AppointmentDate.Value);
        }
    }

    private async Task OnDateChanged()
    {
        _timeSlots.Clear();
        Model.TimeSlot = string.Empty;
        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            _timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
                Model.Doctor, Model.AppointmentDate.Value);
        }
    }

    private async Task HandleSubmit()
    {
        _fieldErrors.Clear();

        // Server-side validation including step 2 fields
        var errors = await AppointmentService.ValidatePatientAsync(
            Model.Email, Model.InsuranceProvider, Model.Doctor, Model.TimeSlot);

        if (errors.Count > 0)
        {
            _fieldErrors = errors;
            return;
        }

        _submitted = true;
    }

    private static bool IsValidEmail(string email)
    {
        try
        {
            var addr = new System.Net.Mail.MailAddress(email);
            return addr.Address == email;
        }
        catch
        {
            return false;
        }
    }
}
"}

